def handle_list_users(params: dict) -> tuple[int, dict]:
    page_str = params.get("page", "1")
    page_size_str = params.get("page_size", "10")

    if not (page_str.isdigit() and page_size_str.isdigit()):
        return 400, {"error": "invalid pagination"}

    page = int(page_str)
    page_size = int(page_size_str)

    if page < 1 or not (1 <= page_size <= 100):
        return 400, {"error": "invalid pagination"}

    all_users = users.get_all_users()
    total = len(all_users)

    start = (page - 1) * page_size
    end = start + page_size

    page_users = all_users[start:end]

    return 200, {
        "users": page_users,
        "page": page,
        "page_size": page_size,
        "total": total,
    }
